        goals: [goal(L('There is a group', 'Hi ha un grup', 'Hay un grupo'), g => (g.groups || []).length > 0), goal(L('The group has its own name', 'El grup té un nom propi', 'El grupo tiene un nombre propio'), g => (g.groups || []).some(x => x.title && x.title !== 'Group')), goal(L('Saved with <kbd>Ctrl S</kbd>', 'Desat amb <kbd>Ctrl S</kbd>', 'Guardado con <kbd>Ctrl S</kbd>'), (g, c) => c.flags.saved)],
